package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static com.google.javascript.jscomp.CheckGlobalThis.shouldTraverse;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen0Test {

    private CheckGlobalThis checker;
    private NodeTraversal t;

    @Before
    public void setUp() {
        checker = new CheckGlobalThis();
        t = mock(NodeTraversal.class);
    }

    private Node mockNode(int type) {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(type);
        return node;
    }

    private Node mockNode(int type, String value) {
        Node node = mockNode(type);
        when(node.getString()).thenReturn(value);
        return node;
    }

    @Test
    public void testNonFunctionNonAssignment() {
        Node n = mockNode(Token.VAR);
        Node parent = mockNode(Token.BLOCK);
        assertTrue(checker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithJsDocConstructor() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);

        // We need to mock the internal getFunctionJsDocInfo call. 
        // Since it's a private method in the same class, in a real scenario 
        // we'd use a spy or rely on the actual implementation if possible.
        // Assuming getFunctionJsDocInfo is part of the class logic.
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(true);
        doReturn(jsDoc).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithJsDocThisType() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.hasThisType()).thenReturn(true);
        doReturn(jsDoc).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithJsDocOverride() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isOverride()).thenReturn(true);
        doReturn(jsDoc).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithNullJsDoc() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(null).when(spyChecker).getFunctionJsDocInfo(n);

        assertTrue(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionInvalidParentType() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.EXPRESSION); // Not BLOCK, SCRIPT, NAME, or ASSIGN
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(null).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionValidParentType() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.ASSIGN);
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(null).when(spyChecker).getFunctionJsDocInfo(n);

        assertTrue(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testAssignmentLeftHandSide() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.STRING);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is the lhs
        assertTrue(checker.shouldTraverse(t, lhs, parent));
    }

    @Test
    public void testAssignmentRightHandSideValid() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.STRING);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getQualifiedName()).thenReturn("a");

        // n is the rhs
        assertTrue(checker.shouldTraverse(t, rhs, parent));
    }

    @Test
    public void testAssignmentRightHandSidePrototypeGetProp() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.GETPROP);
        Node protoNode = mockNode(Token.NAME, "prototype");
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(mockNode(Token.STRING));
        when(lhs.getLastChild()).thenReturn(protoNode);

        Node rhs = mockNode(Token.STRING);
        assertFalse(checker.shouldTraverse(t, rhs, parent));
    }

    @Test
    public void testAssignmentRightHandSideQualifiedPrototype() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.STRING);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getQualifiedName()).thenReturn("Object.prototype.toString");

        assertFalse(checker.shouldTraverse(t, rhs, parent));
    }

    @Test
    public void testNullParent() {
        Node n = mockNode(Token.VAR);
        assertTrue(checker.shouldTraverse(t, n, null));
    }
}
